		w.Header().Set("x-ratelimit-reset-requests", "100ms")
		time.Sleep(10 * time.Millisecond)
		_ = json.NewEncoder(w).Encode(map[string]any{
			"id":     "chatcmpl-1",
			"model":  "gpt-4o",
			"object": "chat.completion",
			"choices": []map[string]any{
				{
					"index": 0,
					"message": map[string]any{
						"role":    "assistant",
						"content": "done",
					},
					"finish_reason": "stop",
				},
			},
			"usage": map[string]int{
				"prompt_tokens":     12,
				"completion_tokens": 5,
				"total_tokens":      17,
			},
		})
	}))
	defer srv.Close()

	p := openai.New(openai.Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   "gpt-4o",
	})

	resp, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{})
	if err != nil {
		t.Fatalf("Chat returned error: %v", err)
	}
	if resp.Content != "done" {
		t.Fatalf("Content = %q, want done", resp.Content)
	}

	cacheRoot := filepath.Join(os.Getenv("FIZEAU_CACHE_DIR"))
	sig, ok := runtimesignals.ReadCached(&discoverycache.Cache{Root: cacheRoot}, "openai")
	if !ok {
		t.Fatal("expected runtime cache entry for openai")
	}
	if sig.Status != runtimesignals.StatusAvailable {
		t.Fatalf("Status = %q, want available", sig.Status)
	}
	if sig.QuotaRemaining == nil || *sig.QuotaRemaining != 42 {
		t.Fatalf("QuotaRemaining = %#v, want 42", sig.QuotaRemaining)
	}
	if sig.RecentP50Latency <= 0 {
		t.Fatalf("RecentP50Latency = %v, want > 0", sig.RecentP50Latency)
	}
	if sig.QuotaResetAt == nil {
		t.Fatal("expected quota reset time to be recorded")
	}
}

func TestChat_RuntimeSignalWritesExhaustedCacheOnFailure(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/chat/completions" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("x-ratelimit-remaining-requests", "0")
		w.Header().Set("x-ratelimit-reset-requests", "1s")
		http.Error(w, `{"error":"boom"}`, http.StatusInternalServerError)
	}))
	defer srv.Close()

	p := openai.New(openai.Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   "gpt-4o",
	})

	_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{})
	if err == nil {
		t.Fatal("expected Chat to fail")
	}

	cacheRoot := filepath.Join(os.Getenv("FIZEAU_CACHE_DIR"))
	sig, ok := runtimesignals.ReadCached(&discoverycache.Cache{Root: cacheRoot}, "openai")
	if !ok {
		t.Fatal("expected runtime cache entry for openai")
	}
	if sig.Status != runtimesignals.StatusExhausted {
		t.Fatalf("Status = %q, want exhausted", sig.Status)
	}
	if sig.QuotaRemaining == nil || *sig.QuotaRemaining != 0 {
		t.Fatalf("QuotaRemaining = %#v, want 0", sig.QuotaRemaining)
	}
	if sig.RecentP50Latency <= 0 {
		t.Fatalf("RecentP50Latency = %v, want > 0", sig.RecentP50Latency)
	}
}

package openai_test

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	agent "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestChatStream_ClassifiesNotImplementedErrorAsCapabilityMissing replays the
// SSE error frame captured against an mlx_lm/lmstudio backend that surfaced
// "NotImplementedError: RotatingKVCache Quantization NYI" mid-stream
// (bead agent-a8915e01). The decoder must hand the agent loop a typed
// ProviderCapabilityMissingError carrying the stable code, the parsed
// capability name, and the original server message — not the opaque
// "received error while streaming: ..." string the openai-go SDK produces.
func TestChatStream_ClassifiesNotImplementedErrorAsCapabilityMissing(t *testing.T) {
	// Wire shape: one SSE data frame with a top-level "error" object. The
	// openai-go ssestream decoder picks up the "error" key via gjson and
	// emits the JSON value as part of "received error while streaming: <ep>".
	frame := `{"error":{"message":"Error in iterating prediction stream: NotImplementedError: RotatingKVCache Quantization NYI"}}`
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		streamSSE(w, []string{frame})
	}))
	defer srv.Close()

	p := openai.New(openai.Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   "qwen3.5-7b",
	})

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	ch, err := p.ChatStream(ctx, []agent.Message{
		{Role: agent.RoleUser, Content: "hello"},
	}, nil, agent.Options{})
	require.NoError(t, err)

	var streamErr error
	for delta := range ch {
		if delta.Err != nil {
			streamErr = delta.Err
		}
	}
	require.Error(t, streamErr, "stream must surface the upstream NotImplementedError")

	var typed *agent.ProviderCapabilityMissingError
	require.True(t, errors.As(streamErr, &typed),
		"err must be a *ProviderCapabilityMissingError; got %T: %v", streamErr, streamErr)
	assert.Equal(t, agent.ProviderCapabilityMissingErrorCode, typed.Code)
	assert.Equal(t, "RotatingKVCache Quantization", typed.Capability,
		"capability extracted from server message must drop the trailing NYI sentinel")
	assert.Contains(t, typed.ServerMessage, "RotatingKVCache Quantization NYI",
		"server message must preserve the upstream text for telemetry")
	assert.True(t, errors.Is(streamErr, agent.ErrProviderCapabilityMissing),
		"errors.Is must match the exported sentinel for routing-layer checks")
	require.NotNil(t, typed.UnwrapCause(),
		"cause should preserve the underlying SDK error for chained debugging")
	assert.Contains(t, typed.UnwrapCause().Error(), "received error while streaming",
		"underlying SDK error must remain accessible via UnwrapCause")
}

// TestChatStream_ClassifiesGenericNotImplementedError covers AC item 1's
// "or any NotImplementedError from the provider" clause: capability names
// other than RotatingKVCache must also be classified, with the parsed
// capability captured for telemetry.
func TestChatStream_ClassifiesGenericNotImplementedError(t *testing.T) {
	frame := `{"error":{"message":"NotImplementedError: SlidingWindowAttention NYI"}}`
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		streamSSE(w, []string{frame})
	}))
	defer srv.Close()

	p := openai.New(openai.Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   "qwen3.5-7b",
	})

	ch, err := p.ChatStream(context.Background(), []agent.Message{
		{Role: agent.RoleUser, Content: "hello"},
	}, nil, agent.Options{})
	require.NoError(t, err)

	var streamErr error
	for delta := range ch {
		if delta.Err != nil {
			streamErr = delta.Err
		}
	}
	require.Error(t, streamErr)

	var typed *agent.ProviderCapabilityMissingError
	require.True(t, errors.As(streamErr, &typed))
	assert.Equal(t, agent.ProviderCapabilityMissingErrorCode, typed.Code)
	assert.Equal(t, "SlidingWindowAttention", typed.Capability)
}

// TestChatStream_UnrelatedStreamErrorIsNotReclassified is the negative case:
// the classifier must leave non-NotImplementedError stream errors alone so
// existing transient-error retry paths (rate limits, network blips) keep
// working unchanged.
func TestChatStream_UnrelatedStreamErrorIsNotReclassified(t *testing.T) {
	frame := `{"error":{"message":"rate limit reached"}}`
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		streamSSE(w, []string{frame})
	}))
	defer srv.Close()

	p := openai.New(openai.Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   "qwen3.5-7b",
	})

	ch, err := p.ChatStream(context.Background(), []agent.Message{
		{Role: agent.RoleUser, Content: "hello"},
	}, nil, agent.Options{})
	require.NoError(t, err)

	var streamErr error
	for delta := range ch {
		if delta.Err != nil {
			streamErr = delta.Err
		}
	}
	require.Error(t, streamErr)

	var typed *agent.ProviderCapabilityMissingError
	assert.False(t, errors.As(streamErr, &typed),
		"non-NotImplementedError stream errors must remain opaque so transient-retry paths are unaffected")

package llamaserver

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"sync"
	"testing"

	agent "github.com/easel/fizeau/internal/core"
	"github.com/stretchr/testify/require"
)

const llamaThinkingModel = "Qwen3.6-27B-UD-Q3_K_XL.gguf"

func TestLlamaserver_EnableThinking_WireBody(t *testing.T) {
	body := captureLlamaserverChatBody(t, agent.ReasoningHigh)

	var reqBody map[string]any
	require.NoError(t, json.Unmarshal(body, &reqBody))

	ctk, ok := reqBody["chat_template_kwargs"].(map[string]any)
	require.True(t, ok, "request body must include chat_template_kwargs: %s", string(body))
	require.Equal(t, true, ctk["enable_thinking"])
	require.NotContains(t, reqBody, "enable_thinking", "top-level enable_thinking must not be emitted: %s", string(body))
}

func TestLlamaserver_EnableThinking_Disabled(t *testing.T) {
	body := captureLlamaserverChatBody(t, agent.ReasoningOff)

	var reqBody map[string]any
	require.NoError(t, json.Unmarshal(body, &reqBody))

	ctk, ok := reqBody["chat_template_kwargs"].(map[string]any)
	require.True(t, ok, "disabled thinking must still use the chat_template_kwargs envelope: %s", string(body))
	require.Equal(t, false, ctk["enable_thinking"])
	require.NotContains(t, reqBody, "enable_thinking", "top-level enable_thinking must not be emitted: %s", string(body))
}

func captureLlamaserverChatBody(t *testing.T, reasoning agent.Reasoning) []byte {
	t.Helper()

	fixture, err := os.ReadFile("testdata/props/llama_props.json")
	require.NoError(t, err)

	var (
		mu   sync.Mutex
		body []byte
	)

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/props":
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write(fixture)
		case "/v1/chat/completions":
			mu.Lock()
			defer mu.Unlock()
			captured, _ := ioReadAll(r.Body)
			body = append([]byte(nil), captured...)
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]any{
				"id":     "chatcmpl-1",
				"model":  llamaThinkingModel,
				"object": "chat.completion",
				"choices": []map[string]any{
					{
						"index": 0,
						"message": map[string]any{
							"role":    "assistant",
							"content": "done",
						},
						"finish_reason": "stop",
					},
				},
				"usage": map[string]int{
					"prompt_tokens":     1,
					"completion_tokens": 1,
					"total_tokens":      2,
				},
			})
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(srv.Close)

	p := New(Config{
		BaseURL: srv.URL + "/v1",
		Model:   llamaThinkingModel,
	})

	_, err = p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{
		Reasoning: reasoning,
	})
	require.NoError(t, err)

	mu.Lock()
	defer mu.Unlock()
	require.NotEmpty(t, body, "expected a captured request body")
	return body
}

func ioReadAll(r io.Reader) ([]byte, error) {
	return io.ReadAll(r)
}
